const patternMotion=({keyframes,extraCss='',reactExample='',previewData=null,loop=false,useCase,caution,...motion})=>{
 const id=motion.id,name=`klic-motion-${id}`,selector=`.motion-pattern-stage[data-motion-type=${id}] .${name}`;
 const css=`.${name}.is-active, ${selector} { animation: ${name} ${motion.durationMs}ms ${motion.easing} ${loop?'infinite':'both'}; }\n@keyframes ${name} { ${keyframes} }\n@media (prefers-reduced-motion: reduce) { .${name}.is-active, ${selector} { animation: none !important; transform: none !important; opacity: 1 !important; clip-path: none !important; filter: none !important; } }\n${extraCss}`;
 const component=id.split('-').map(part=>part[0].toUpperCase()+part.slice(1)).join('');
 const segmentedReact=previewData?.segment?`export function ${component}({ children, active = true }) {\n const parts = ${previewData.segment==='word'?"String(children).split(/(\\s+)/u)":"Array.from(String(children))"};\n return <span aria-label={String(children)}>{parts.map((part,index) => <span key={index} aria-hidden="true" className={'${name}' + (active ? ' is-active' : '')} style={{'--motion-order':index}}>{part}</span>)}</span>;\n}\n\n/* Include the paired CSS; reduced motion shows the complete text immediately. */`:null;
 const react=reactExample||segmentedReact||(String(motion.category).startsWith('text-')?`export function ${component}({ children, active = true }) {\n return <span className={'${name}' + (active ? ' is-active' : '')}>{children}</span>;\n}\n\n/* Keep the original text in the DOM; CSS honors prefers-reduced-motion: reduce. */`:`export function ${component}({ active }) {\n return <span className={'${name}' + (active ? ' is-active' : '')} aria-hidden="true" />;\n}\n\n/* The CSS also honors prefers-reduced-motion: reduce. */`);
 return freezeMotion({...motion,source:'klic-authored',previewType:id,staggerMs:0,useCases:[useCase],cautions:[caution],reducedMotion:motion.reducedMotion||copy('중간 프레임을 생략하고 의미가 유지되는 정적 상태를 표시합니다.','Skip intermediate frames and show a static state that preserves meaning.'),preview:previewData||{label:copy('동작 미리보기','Motion preview'),title:motion.title,description:motion.summary},implementation:{css,react}});
};

export const MOTION_CATALOG=Object.freeze([...BASE_MOTION_CATALOG,...patternRecipes.map(patternMotion),...presentationTextRecipes.map(patternMotion)]);

export const getMotion=id=>MOTION_CATALOG.find(item=>item.id===id)||null;
